-- Sparkora Code Lab: run in Supabase SQL editor as project owner.
create extension if not exists pgcrypto;
create type public.user_role as enum ('teacher','student');
create type public.access_state as enum ('active','expired','suspended','revoked');
create type public.renewal_state as enum ('pending','approved','rejected');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,username text not null unique,role public.user_role not null,created_at timestamptz not null default now());
create table public.teachers(id uuid primary key default gen_random_uuid(),profile_id uuid not null unique references public.profiles(id) on delete cascade,created_at timestamptz not null default now());
create table public.students(id uuid primary key default gen_random_uuid(),profile_id uuid not null unique references public.profiles(id) on delete cascade,teacher_id uuid not null references public.teachers(id),grade integer not null check(grade between 1 and 8),created_at timestamptz not null default now());
create table public.student_access(id uuid primary key default gen_random_uuid(),student_id uuid not null unique references public.students(id) on delete cascade,status public.access_state not null default 'active',starts_at timestamptz not null default now(),expires_at timestamptz not null,updated_at timestamptz not null default now());
create table public.renewal_requests(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.students(id) on delete cascade,teacher_id uuid not null references public.teachers(id),status public.renewal_state not null default 'pending',requested_at timestamptz not null default now(),reviewed_at timestamptz);
create unique index one_pending_request on public.renewal_requests(student_id) where status='pending';
create table public.access_history(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.students(id),teacher_id uuid not null references public.teachers(id),action text not null,previous_expiry timestamptz,new_expiry timestamptz,created_at timestamptz not null default now());
create table public.courses(id uuid primary key default gen_random_uuid(),title text not null,description text not null default '',grade_min int not null check(grade_min between 1 and 8),grade_max int not null check(grade_max between 1 and 8));
create table public.lessons(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,title text not null,content text not null default '',lesson_order integer not null);
create table public.student_progress(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.students(id) on delete cascade,lesson_id uuid not null references public.lessons(id) on delete cascade,completion_status text not null default 'not_started',updated_at timestamptz not null default now(),unique(student_id,lesson_id));
create index idx_students_teacher on public.students(teacher_id);
create index idx_renewal_teacher on public.renewal_requests(teacher_id,status);
create index idx_access_expiry on public.student_access(expires_at);
create or replace function public.is_teacher_of(p_student uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from students s join teachers t on t.id=s.teacher_id where s.id=p_student and t.profile_id=auth.uid()) $$;
create or replace function public.my_student_id() returns uuid language sql stable security definer set search_path=public as $$ select id from students where profile_id=auth.uid() limit 1 $$;
create or replace function public.my_teacher_id() returns uuid language sql stable security definer set search_path=public as $$ select id from teachers where profile_id=auth.uid() limit 1 $$;
create or replace function public.has_active_access() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from students s join student_access a on a.student_id=s.id where s.profile_id=auth.uid() and a.status='active' and a.starts_at<=now() and a.expires_at>now()) $$;
create or replace function public.request_access_renewal() returns void language plpgsql security definer set search_path=public as $$ declare s public.students%rowtype;begin select * into s from students where profile_id=auth.uid();if s.id is null then raise exception 'Student account required';end if;if public.has_active_access() then raise exception 'Your access is still active';end if;insert into renewal_requests(student_id,teacher_id) values(s.id,s.teacher_id) on conflict do nothing;end $$;
create or replace function public.teacher_manage_access(p_student_id uuid,p_action text,p_days integer default 0) returns void language plpgsql security definer set search_path=public as $$ declare old_expiry timestamptz; new_expiry timestamptz; t_id uuid;begin if not public.is_teacher_of(p_student_id) then raise exception 'Unauthorized';end if;select id into t_id from teachers where profile_id=auth.uid();select expires_at into old_expiry from student_access where student_id=p_student_id for update;if old_expiry is null then raise exception 'Access record missing';end if;if p_action='renew' then if p_days<1 or p_days>365 then raise exception 'Duration must be 1–365 days';end if;new_expiry=greatest(now(),old_expiry)+make_interval(days=>p_days);update student_access set status='active',starts_at=least(starts_at,now()),expires_at=new_expiry,updated_at=now() where student_id=p_student_id;elsif p_action in ('suspend','revoke') then update student_access set status=p_action::access_state,updated_at=now() where student_id=p_student_id;new_expiry=old_expiry;else raise exception 'Invalid action';end if;insert into access_history(student_id,teacher_id,action,previous_expiry,new_expiry) values(p_student_id,t_id,p_action,old_expiry,new_expiry);end $$;
create or replace function public.teacher_review_renewal(p_request_id uuid,p_approve boolean,p_days integer default 0) returns void language plpgsql security definer set search_path=public as $$ declare r public.renewal_requests%rowtype;begin select * into r from renewal_requests where id=p_request_id for update;if r.id is null or r.status<>'pending' or not public.is_teacher_of(r.student_id) then raise exception 'Request not found or unauthorized';end if;if p_approve then perform public.teacher_manage_access(r.student_id,'renew',p_days);end if;update renewal_requests set status=case when p_approve then 'approved'::renewal_state else 'rejected'::renewal_state end,reviewed_at=now() where id=p_request_id;end $$;
revoke all on function public.request_access_renewal() from public;grant execute on function public.request_access_renewal() to authenticated;
revoke all on function public.teacher_manage_access(uuid,text,integer) from public;grant execute on function public.teacher_manage_access(uuid,text,integer) to authenticated;
revoke all on function public.teacher_review_renewal(uuid,boolean,integer) from public;grant execute on function public.teacher_review_renewal(uuid,boolean,integer) to authenticated;
alter table profiles enable row level security;alter table teachers enable row level security;alter table students enable row level security;alter table student_access enable row level security;alter table renewal_requests enable row level security;alter table access_history enable row level security;alter table courses enable row level security;alter table lessons enable row level security;alter table student_progress enable row level security;
create policy profile_select on profiles for select to authenticated using(id=auth.uid() or exists(select 1 from students s where s.profile_id=profiles.id and public.is_teacher_of(s.id)));
create policy teacher_select on teachers for select to authenticated using(profile_id=auth.uid());
create policy student_select on students for select to authenticated using(profile_id=auth.uid() or public.is_teacher_of(id));
create policy access_select on student_access for select to authenticated using(student_id=public.my_student_id() or public.is_teacher_of(student_id));
create policy renewal_select on renewal_requests for select to authenticated using(student_id=public.my_student_id() or public.is_teacher_of(student_id));
create policy history_select on access_history for select to authenticated using(student_id=public.my_student_id() or public.is_teacher_of(student_id));
create policy courses_select on courses for select to authenticated using(exists(select 1 from teachers where profile_id=auth.uid()) or (public.has_active_access() and exists(select 1 from students s where s.profile_id=auth.uid() and s.grade between courses.grade_min and courses.grade_max)));
create policy lessons_select on lessons for select to authenticated using(exists(select 1 from courses c where c.id=lessons.course_id));
create policy progress_select on student_progress for select to authenticated using(student_id=public.my_student_id() or public.is_teacher_of(student_id));
-- No client INSERT/UPDATE/DELETE policies for access, role, student or renewal records.
-- All writes use audited SECURITY DEFINER functions or a verified service-role Edge Function.
insert into courses(title,description,grade_min,grade_max) values('Little Coders','Print, numbers and text',1,2),('Creative Coders','Variables and conditions',3,4),('Logic Builders','Loops, lists and functions',5,6),('Python Explorers','Dictionaries and mini projects',7,8);
